      "definition": "字形靠中间一根纵贯的竖（常常是竖钩）撑住：这根竖处在字的中间位置，作用像房屋的「顶梁柱」，让上半部分的笔画有依托。竖要垂直向下走，字才挺拔、劲健有力、显出雄强气势，整字重心不倾斜、稳重；其余笔画即使有倾斜或弯曲，也向左右两边伸展出去。最适合笔画少的字和独体字式的结构，复杂结构则不再适用这条规律。",
