      "definition": "两个朝向相同、笔画相同的笔画放在一起或靠得很近时（最典型是两个撇），不能写成雷同；要用粗细对比、弧度对比、高度错落、斜势对比把它们拉开。老师说停字左边两个撇「一个完全直挺、一个带弧度」，虽然直挺地写也可以，但「怎么着他都和左边这个笔画雷同，不好看」。",
