      "definition": "写左右结构的字，先定左右两部分的分配关系：左上右下、左中右、左下右上、左大右小、左宽右窄、左宽窄又宽。难点在偏旁本身的大小、它占据整字哪个位置、有没有伸展笔画，以及有伸展笔画时怎么跟右边穿插互让。",
