      "conflict": true,
      "variants": [
        {
          "text": "撇捺要打开、捺要伸展；收得太紧，下部空间会被压缩，字就不舒展。",
          "part": 13,
          "title": "第13节 左偏旁及书写规律",
          "font": "硬笔"
        },
        {
          "text": "带反文旁的字，撇和捺一定要打开，把字势撑开、把伸展开现出来；捺一定要伸展出去。反文旁遇到的字非常多，这条要特别注意。",
          "part": 17,
          "title": "第17节 右偏旁及书写规律",
          "font": "硬笔"
        },
        {
          "text": "字头的撇与捺要能开合：撇捺伸展出去、撑开下部空间（人字头、大字头、寒字中间）。寒字上部收紧，正是为了让撇捺有地方开合；开合的标准不是角度表，而是「能给它开合」。",
          "part": 22,
          "title": "第22节 字头及书写规律",
          "font": "硬笔"
        },
        {
          "text": "字头里的撇和捺要能开合：两个撇的夹角左边大一点，好给下边留出足够的空间；撇捺交点不要过低，交点过低中间的肚子会大、整个字显头空。夂字头和父字头都按这一条办。",
          "part": 23,
          "title": "第23节 字头及书写规律",
          "font": "硬笔"
        },
        {
          "text": "字头的撇与捺要能开合：撇捺伸展出去、撑开下部空间；春字头、卷字头都要求撇捺开合，捺一定要伸展出去。",
          "part": 24,
          "title": "第24节 字头及书写规律",
          "font": "硬笔"
        },
        {
          "text": "撇捺的开合要看字底：想写成下托上，就把撇和捺收缩起来（杰字里撇改成一个点、四点扩出去）；想写成上盖下，撇和捺就完全伸展出去。整体只要协调即可——最左边那笔稍微伸展、右边那笔稍微收缩，不要刻意地只伸展一边。",
          "part": 25,
          "title": "第25节 字底及书写规律",
          "font": "硬笔"
        }
      ]
