      "definition": "撇和横都要往右上倾斜。第一个顿笔撇本来就带斜度；如果把横写得很平、竖又垂直向下，一个字里就同时出现「往右上走」「垂直直出」「往下走」三个方向的笔画，方向太多字就不稳。所以要顺着第一个撇往右上走一点，横也往右上去——在横平竖直的基础上把字的形态变化多一点，「右上走一点，取一下势」。",
