      "definition": "斤字旁的悬针竖一定落在偏旁的中心线上。常规思维容易把竖放到右边去，那样偏旁就写胖了；作为独体字这样可以，作为偏旁不行。目标是「横往右上伸展、竖往下伸展」。悬针竖还要顿笔重起、收笔轻，把尖儿展现出来。",
