      "definition": "像虎字头这样占空间大的上部构件，上部的笔画和间距要收紧，把下部的空间让出来——「该收的收、该放的放」，字才自然舒畅；上部松了，下面的伸展部分就没地方去了。注意与 p14 已有的「右部上紧下松」（左右结构里右部自身的上紧下松）层级不同：这里说的是上下结构里上、下两段之间的关系。",
