      "conflict": true,
      "variants": [
        {
          "text": "框内笔画要上紧下松：因字上部略显紧、下部略给他放开，字才好看。上部一旦放开就头大了，不好看；下部放开是把空间让给下面伸展的笔画。",
          "part": 21,
          "title": "第21节 字框及书写规律",
          "font": "硬笔"
        },
        {
          "text": "字头占空间，上部就要收紧，把下面的空间让出来：寒字上部一定要收紧，否则写完猛然回首撇捺没地方伸展；夸写完大字头之后，下边那个横尽可能往里靠，把空间平分开。",
          "part": 22,
          "title": "第22节 字头及书写规律",
          "font": "硬笔"
        },
        {
          "text": "字头占空间，上部就要收紧，把下面的空间让出来：采字写完爪字头就是上紧下松，下边木的撇捺才有地方伸展。",
          "part": 24,
          "title": "第24节 字头及书写规律",
          "font": "硬笔"
        },
        {
          "text": "上下结构里上、下两段之间的关系：象字上部明显不能写太大，把上部收紧、让出空间，下部的撇、弯钩、捺才伸展得开，整体呈现上紧下松（也可以说上收下放）。",
          "part": 26,
          "title": "第26节 字底及书写规律",
          "font": "硬笔"
        }
      ]
