      "variants": [
        {
          "text": "部件内部各笔画之间的间距要一致：扁四头内部两个竖把空间平分，不能忽大忽小。",
          "part": 24,
          "title": "第24节 字头及书写规律",
          "font": "硬笔"
        },
        {
          "text": "部件内部各部分的间距要基本一致、不能忽大忽小：四点底四个点三个间距（中间两个点不能靠得太近）；皿字底内部的间距要保证，还可以稍微往外扩一点；心字底左点、卧钩、右点之间要留出均匀的空间——笔画越写越长、间距越拉越大，字就容易写胖。",
          "part": 25,
          "title": "第25节 字底及书写规律",
          "font": "硬笔"
        },
        {
          "text": "部件内部各部分的间距要基本一致：十字底里边的两个撇可以平分间距；象字里的口，横竖要多紧凑就多紧凑；子字笔画多、上中下间距又高，任何一段跑了整个字基本上也就跑了。",
          "part": 26,
          "title": "第26节 字底及书写规律",
          "font": "硬笔"
        }
      ]
