      "definition": "框内各部分的空间要分布均匀。网字里边的撇点分布要匀——不要某处特别紧、另一处空着；问字里边的口，口字的上、下、左、右空间要一致，口写大了又写小了都不行。均匀不等于拿尺子量精确到零点几毫米，写出来以后没有任何一处显得特别紧、也没有任何一处显得特别松就算到位。",
