      "definition": "门字框的竖钩一定要挺住——竖钩一软，整个字都软。钩的地方必须是一个重笔，轻薄地处理这个钩他挺不住，要缓慢地下来再出钩。竖钩起笔处的内收来自某个碑帖的书写习惯（字幕此处 ASR 乱码，碑名无法确证），是取法乎上，不是乱写；老师自己的习惯是往里收一点，更显精神。",
