      "font": "硬笔",
      "definition": "起笔点与上一笔收笔点对齐，首尾才呼应：夸字的勾要收在中心，起笔点对准勾的收笔点；冠字里寸的竖钩起笔点落在横钩的收笔点上（扩出来字中间会显得很胖）；合字里口的下竖起笔、横折折下来处都要落在横的起笔点上，口才在正中心。",
