      "definition": "以《多宝塔》为例，楷书的布白是整齐一律的：纵观整体，无论是原碑帖还是临摹作品，字与字、行与行之间排列均为等距；字势的宽度长短不同（字幕原词作「鞋子的宽度长短」）、造型不同，产生局部的参差变化，给人一种稳定庄重的视觉效果。这种形式最适合法度严谨的楷书。",
