      "definition": "行草书变化多端、丰富多彩，因字赋形、不刻意布置，在多样性、变化性中有着十分和谐统一的关系。以《兰亭序》和《书谱》为例，两幅字给人的感受是静中有动；无论是字的造型、长短、斜正的变化，都有着或轻或重的节奏感。（紧接「静中有动」的「字中柔情的」与「长短期正」两处字幕未确证，原词保留。）",
